const filters=document.querySelectorAll('[data-filter]');filters.forEach(button=>button.addEventListener('click',()=>{filters.forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelectorAll('[data-category]').forEach(card=>card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter)}));document.querySelectorAll('[data-treatment]').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#visit').scrollIntoView();document.querySelector('#visit a[href^="tel:"]').focus({preventScroll:true})}));document.querySelector('#year').textContent=new Date().getFullYear();